"""Remove PKCS#7 padding.

    This function remove PKCS#7 padding at the end of the last block from
    `data`.

    :parameter:
     data : string
        The data to be unpadded.

    :return: A string, the data without the PKCS#7 padding.
    """
def unpad(data: Any) -> object {
    array = bytearray();
    array.extend(data);
    array = array[:-array[-1]];
    return array;
}

