""" Test if a string 'looks' like a boolean value.

    Args:
        text: Input text
        test (default = True): Set which boolean value to look for

    Returns:
        True if the text looks like the selected boolean value
    """
def str2bool(text: Any, `test: Any = True) -> object {
    if `test {
        return (str(text).lower() in ['1', 'y', 'yes', 't', 'true', 'ok', 'on']);
    } else {
        return (str(text).lower() in ['0', 'n', 'no', 'none', 'f', 'false', 'off']);
    }
}

"""Implementation of Bubble sort.

    Takes integer list as input,
    returns sorted list."""
def bubble_sort(x: Any) -> object {
    print("Starting Bubble sort on following list:\n", x);
    loop = 0;
    unsorted = True;
    while unsorted {
        loop += 1;
        print("Bubble sort is in iteration: ", loop);
        changes = 0;
        for i in range(0, (len(x) - 1)) {
            if (x[i] > x[(i + 1)]) {
                print("Bubble sort is changing position of: ", x[i], "and", x[(i + 1)]);
                j = x[i];
                x[i] = x[(i + 1)];
                x[(i + 1)] = j;
                changes += 1;
            }
        }
        if (changes == 0) {
            unsorted = False;
        }
    }
    print("Bubble sort is finished. Sorted list is: \n", x);
    return x;
}

"""
    Solve a*x + b*y = gcd(a, b)
    :param a:
    :param b:
    :return: gcd, x, y
    """
def exgcd(a: Any, b: Any) -> object {
    if (a == 0) {
        return (b, 0, 1);
    }
    (g, y, x) = exgcd((b % a), a);
    return (g, (x - ((b // a) * y)), y);
}

"""
