    :param b: model parameter
    :param m: model parameter
    :return: variance of model
    """
def model_var_calculate(x: Any, p: Any, q: Any, n: Any) -> object {
    def alpha_(x: Any) -> object {
        return (n * ((p * pow(x, 3)) + (q * (x * x)) + ((1 - p - q) * x)));
    }
    def beta_(x: Any) -> object {
        return (n - alpha_(x));
    }
    return (
        (alpha_(x) * beta_(x))
        / (((alpha_(x) + beta_(x)) ** 2) * (alpha_(x) + beta_(x) + 1))
    );
}

